window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9c03800e3d6f37bf"]={"versions": [{"id": "FIG-9c03800e3d6f37bf", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Algorithmusablaufs des Schritts „Compute CRC“ innerhalb der E2E-Transformator- bzw. Bibliotheksfunktion <code>E2E_P05Forward()</code>. Das Diagramm konkretisiert die AUTOSAR E2E-Protokollspezifikation für das Profil 5 (E2E Profile 5) zur standardisierten Berechnung der zyklischen Redundanzprüfung (CRC-16) über Nutzdaten und Daten-ID.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktion/Aktivitätskontext: <code>E2E_P05Forward()</code></li>\n<li>Externe CRC-Berechnungsroutine: <code>Crc_CalculateCRC16(Crc_DataPtr, Crc_Length, Crc_StartValue16, Crc_IsFirstCall)</code></li>\n<li>Konfigurations- und Zustandsdaten:</li>\n<li><code>Config-&gt;Offset</code>: Byte-Position des 2 Byte langen CRC-Feldes im Datenpuffer <code>Data</code></li>\n<li><code>Config-&gt;DataID</code>: 16-Bit-Bezeichner der Kommunikationsbeziehung (E2E Data ID)</li>\n<li><code>ForwardStatus</code>: Status der Forwarding-Operation (geprüft auf <code>E2E_P_ERROR</code>)</li>\n<li><code>Length</code>: Gesamtlänge des Datenbereichs in Bytes</li>\n<li><code>Data[]</code>: Byte-Array der zu übertragenden/weiterzuleitenden Nachricht</li>\n<li><code>ComputedCRC</code>: Lokale 16-Bit-Variable (<code>uint16</code>) zur Akkumulation des CRC-Wertes</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start über Initialknoten.</li>\n<li>Erste Verzweigung (<code>Config-&gt;Offset &gt; 0</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Zweiteilige Berechnung der Nutzdaten-CRC unter Aussparung des CRC-Felds:</li>\n</ul>\n<p class=\"fig-p\">a) <code>uint16 ComputedCRC = Crc_CalculateCRC16(&amp;Data[0], Offset, 0xFFFF, TRUE)</code> über den Datenabschnitt vor dem Offset.</p>\n<p class=\"fig-p\">b) <code>ComputedCRC = Crc_CalculateCRC16(&amp;Data[Offset+2], Length - Offset - 2, ComputedCRC, FALSE)</code> über den Datenabschnitt nach dem Offset.</p>\n<ul class=\"fig-list\">\n<li><code>[FALSE]</code>: Einteilige Berechnung, da kein Datenabschnitt vor dem Offset existiert:</li>\n</ul>\n<p class=\"fig-p\"><code>uint16 ComputedCRC = Crc_CalculateCRC16(&amp;Data[Offset+2], Length - Offset - 2, 0xFFFF, TRUE)</code>.</p>\n<ol class=\"fig-list\">\n<li>Zusammenführung der Nutzdatenpfade.</li>\n<li>Zweite Verzweigung (<code>if ForwardStatus == E2E_P_ERROR</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[FALSE]</code> (Regulärer Fall): Akkumulation der regulären DataID in zwei Aufrufen (Little-Endian / Byte-weise):</li>\n</ul>\n<p class=\"fig-p\">a) Low-Byte: <code>ComputedCRC = Crc_CalculateCRC16(Config-&gt;DataID &amp; 0xFF, 1, ComputedCRC, FALSE)</code></p>\n<p class=\"fig-p\">b) High-Byte: <code>ComputedCRC = Crc_CalculateCRC16((Config-&gt;DataID &gt;&gt; 8) &amp; 0xFF, 1, ComputedCRC, FALSE)</code></p>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code> (Fehlerfall zur Fehlersimulation / Markierung fehlerhafter Weiterleitung): Akkumulation der modifizierten DataID (<code>DataID + 1</code>):</li>\n</ul>\n<p class=\"fig-p\">a) Low-Byte: <code>ComputedCRC = Crc_CalculateCRC16((Config-&gt;DataID + 1) &amp; 0xFF, 1, ComputedCRC, FALSE)</code></p>\n<p class=\"fig-p\">b) High-Byte: <code>ComputedCRC = Crc_CalculateCRC16(((Config-&gt;DataID + 1) &gt;&gt; 8) &amp; 0xFF, 1, ComputedCRC, FALSE)</code></p>\n<ol class=\"fig-list\">\n<li>Zusammenführung der Pfade und Übergang in den Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf ist gemäß Anforderung <code>[PRS_E2E_00621]</code> normativ für Implementierungen von E2E Profile 5. Er stellt sicher, dass das 2-Byte-CRC-Feld (<code>Offset</code> bis <code>Offset+1</code>) nicht in die Prüfsummenberechnung einfließt. Bei Weiterleitungsfehlern (<code>ForwardStatus == E2E_P_ERROR</code>) wird gezielt eine falsche Prüfsumme mittels <code>DataID + 1</code> generiert, um nachfolgende Empfänger zur Erkennung eines ungültigen E2E-Zustands zu zwingen. Entwickler müssen beachten, dass die CRC-Berechnung sequentiell über die CRC-Bibliothek (<code>Crc_CalculateCRC16</code>) mit akkumulierendem Startwert (<code>Crc_IsFirstCall: FALSE</code>) fortgeführt wird.</p>"}, {"id": "FIG-d871e1b02ad33b1c", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Algorithmusablaufs des Schritts „Compute CRC“ innerhalb der E2E-Transformator- bzw. Bibliotheksfunktion <code>E2E_P05Forward()</code>. Das Diagramm konkretisiert die AUTOSAR E2E-Protokollspezifikation für das Profil 5 (E2E Profile 5) zur standardisierten Berechnung der zyklischen Redundanzprüfung (CRC-16) über Nutzdaten und Daten-ID.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktion/Aktivitätskontext: <code>E2E_P05Forward()</code></li>\n<li>Externe CRC-Berechnungsroutine: <code>Crc_CalculateCRC16(Crc_DataPtr, Crc_Length, Crc_StartValue16, Crc_IsFirstCall)</code></li>\n<li>Konfigurations- und Zustandsdaten:</li>\n<li><code>Config-&gt;Offset</code>: Byte-Position des 2 Byte langen CRC-Feldes im Datenpuffer <code>Data</code></li>\n<li><code>Config-&gt;DataID</code>: 16-Bit-Bezeichner der Kommunikationsbeziehung (E2E Data ID)</li>\n<li><code>ForwardStatus</code>: Status der Forwarding-Operation (geprüft auf <code>E2E_P_ERROR</code>)</li>\n<li><code>Length</code>: Gesamtlänge des Datenbereichs in Bytes</li>\n<li><code>Data[]</code>: Byte-Array der zu übertragenden/weiterzuleitenden Nachricht</li>\n<li><code>ComputedCRC</code>: Lokale 16-Bit-Variable (<code>uint16</code>) zur Akkumulation des CRC-Wertes</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start über Initialknoten.</li>\n<li>Erste Verzweigung (<code>Config-&gt;Offset &gt; 0</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Zweiteilige Berechnung der Nutzdaten-CRC unter Aussparung des CRC-Felds:</li>\n</ul>\n<p class=\"fig-p\">a) <code>uint16 ComputedCRC = Crc_CalculateCRC16(&amp;Data[0], Offset, 0xFFFF, TRUE)</code> über den Datenabschnitt vor dem Offset.</p>\n<p class=\"fig-p\">b) <code>ComputedCRC = Crc_CalculateCRC16(&amp;Data[Offset+2], Length - Offset - 2, ComputedCRC, FALSE)</code> über den Datenabschnitt nach dem Offset.</p>\n<ul class=\"fig-list\">\n<li><code>[FALSE]</code>: Einteilige Berechnung, da kein Datenabschnitt vor dem Offset existiert:</li>\n</ul>\n<p class=\"fig-p\"><code>uint16 ComputedCRC = Crc_CalculateCRC16(&amp;Data[Offset+2], Length - Offset - 2, 0xFFFF, TRUE)</code>.</p>\n<ol class=\"fig-list\">\n<li>Zusammenführung der Nutzdatenpfade.</li>\n<li>Zweite Verzweigung (<code>if ForwardStatus == E2E_P_ERROR</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[FALSE]</code> (Regulärer Fall): Akkumulation der regulären DataID in zwei Aufrufen (Little-Endian / Byte-weise):</li>\n</ul>\n<p class=\"fig-p\">a) Low-Byte: <code>ComputedCRC = Crc_CalculateCRC16(Config-&gt;DataID &amp; 0xFF, 1, ComputedCRC, FALSE)</code></p>\n<p class=\"fig-p\">b) High-Byte: <code>ComputedCRC = Crc_CalculateCRC16((Config-&gt;DataID &gt;&gt; 8) &amp; 0xFF, 1, ComputedCRC, FALSE)</code></p>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code> (Fehlerfall zur Fehlersimulation / Markierung fehlerhafter Weiterleitung): Akkumulation der modifizierten DataID (<code>DataID + 1</code>):</li>\n</ul>\n<p class=\"fig-p\">a) Low-Byte: <code>ComputedCRC = Crc_CalculateCRC16((Config-&gt;DataID + 1) &amp; 0xFF, 1, ComputedCRC, FALSE)</code></p>\n<p class=\"fig-p\">b) High-Byte: <code>ComputedCRC = Crc_CalculateCRC16(((Config-&gt;DataID + 1) &gt;&gt; 8) &amp; 0xFF, 1, ComputedCRC, FALSE)</code></p>\n<ol class=\"fig-list\">\n<li>Zusammenführung der Pfade und Übergang in den Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf ist gemäß Anforderung <code>[PRS_E2E_00621]</code> normativ für Implementierungen von E2E Profile 5. Er stellt sicher, dass das 2-Byte-CRC-Feld (<code>Offset</code> bis <code>Offset+1</code>) nicht in die Prüfsummenberechnung einfließt. Bei Weiterleitungsfehlern (<code>ForwardStatus == E2E_P_ERROR</code>) wird gezielt eine falsche Prüfsumme mittels <code>DataID + 1</code> generiert, um nachfolgende Empfänger zur Erkennung eines ungültigen E2E-Zustands zu zwingen. Entwickler müssen beachten, dass die CRC-Berechnung sequentiell über die CRC-Bibliothek (<code>Crc_CalculateCRC16</code>) mit akkumulierendem Startwert (<code>Crc_IsFirstCall: FALSE</code>) fortgeführt wird.</p>"}], "trans": [{"from": "FIG-9c03800e3d6f37bf", "to": "FIG-d871e1b02ad33b1c", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
